def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]
    prefix_len = len(prefix)
    suffix_len = len(suffix)
    s_len = len(s)

    # Loop through and find the start of the prefix in s
    for i in range(s_len - prefix_len + 1):
        if s[i:i + prefix_len] == prefix:
            # Check all possible positions where the suffix can fit after matching any number of characters indicated by `*`
            for j in range(0, s_len - (i + prefix_len) + 1):
                if s[i + prefix_len + j:i + prefix_len + j + suffix_len] == suffix:
                    return True
    return False

