from typing import List
import math


def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a


def lcm(a: int, b: int) -> int:
    return (a * b) // gcd(a, b)


def maxLength(nums: List[int]) -> int:
    n = len(nums)
    max_len = 0

    for start in range(n):
        product = 1
        current_gcd = 0
        current_lcm = 1
        for end in range(start, n):
            product *= nums[end]
            current_gcd = gcd(current_gcd, nums[end]) if current_gcd else nums[end]
            current_lcm = lcm(current_lcm, nums[end])

            if product == current_gcd * current_lcm:
                max_len = max(max_len, end - start + 1)

    return max_len

from typing import List

def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    rows = len(grid)
    for i in range(rows):
        if i % 2 == 0:
            # Traverse right
            for j in range(0, len(grid[i]), 2):
                result.append(grid[i][j])
        else:
            # Traverse left
            for j in range(len(grid[i]) - 1, -1, -1):
                if j % 2 == 1:  # Only include odd indices
                    result.append(grid[i][j])
    return result

