from typing import List


def largestInteger(nums: List[int], k: int) -> int:
    from collections import defaultdict
    count = defaultdict(int)
    n = len(nums)

    # Create a count of occurrences of each integer in each subarray of size k
    for i in range(n - k + 1):
        subarray = set(nums[i:i + k])  # Unique elements in the current subarray
        for num in subarray:
            count[num] += 1

    # Find the largest integer that appears in exactly one subarray
    largest_missing = -1
    for num, cnt in count.items():
        if cnt == 1:
            largest_missing = max(largest_missing, num)

    return largest_missing

