from typing import List


def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[-float('inf')] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = max(coins[0][0], 0)  # Start at (0, 0) with initial coins

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue  # Skip the starting cell which is already initialized
            # Max coins coming from the top
            if i > 0:
                dp[i][j] = max(dp[i][j], dp[i - 1][j] + (coins[i][j] if coins[i][j] >= 0 else 0))
            # Max coins coming from the left
            if j > 0:
                dp[i][j] = max(dp[i][j], dp[i][j - 1] + (coins[i][j] if coins[i][j] >= 0 else 0))
            # Handle robbers (negative coins) by considering neutralization
            if coins[i][j] < 0:
                # Use neutralization on the current robber cell
                if i > 0 and dp[i - 1][j] >= 0:
                    dp[i][j] = max(dp[i][j], dp[i - 1][j])  # Avoiding using the cell if not neutralizing
                if j > 0 and dp[i][j - 1] >= 0:
                    dp[i][j] = max(dp[i][j], dp[i][j - 1])  # Avoiding using the cell if not neutralizing
                # Check if we neutralize the current cell
                if dp[i - 1][j] >= 0:
                    dp[i][j] = max(dp[i][j], dp[i - 1][j] - coins[i][j])  # Neutralize from above
                if dp[i][j - 1] >= 0:
                    dp[i][j] = max(dp[i][j], dp[i][j - 1] - coins[i][j])  # Neutralize from left

    # The optimal amount at the bottom-right corner
    return max(dp[m - 1][n - 1], 0)

