def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    from collections import defaultdict, deque

    edges.sort(key=lambda x: x[2])  # Sort edges by weight
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    def bfs(start_node, max_weight):
        visited = [False] * n
        queue = deque([start_node])
        visited[start_node] = True
        while queue:
            node = queue.popleft()
            for neighbor, weight in graph[node]:
                if not visited[neighbor] and weight <= max_weight:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return visited

    low, high = 1, max(weight for _, _, weight in edges)
    result = -1

    while low <= high:
        mid = (low + high) // 2
        # Check reachability to node 0 from all nodes with max weight <= mid
        reachable_from_all = True
        for i in range(n):
            visited = bfs(i, mid)
            if not visited[0]:
                reachable_from_all = False
                break
        # Check if each node has at most `threshold` outgoing edges
        outgoing_count = defaultdict(int)
        for u, v, w in edges:
            if w <= mid:
                outgoing_count[u] += 1
        if reachable_from_all and all(count <= threshold for count in outgoing_count.values()):
            result = mid
            high = mid - 1
        else:
            low = mid + 1

    return result

