from typing import List


def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[float('inf')] * 3 for _ in range(n)]

    # Initialize the first house cost
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill the dp table for the first half of houses
    for i in range(1, n // 2 + 1):
        for j in range(3):
            for k in range(3):
                if j != k:
                    dp[i][j] = min(dp[i][j], dp[i - 1][k] + cost[i][j])

    # Fill the dp table for the second half of houses
    for i in range(n // 2):
        for j in range(3):
            for k in range(3):
                if j != k:
                    dp[n - 1 - i][j] = min(dp[n - 1 - i][j], dp[n // 2 + i - 1][k] + cost[n - 1 - i][j])

    return min(dp[n - 1])

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    user_offline_time = [0] * numberOfUsers

    for event in events:
        event_type, timestamp, *args = event
        timestamp = int(timestamp)

        # Update online status for users that should come online
        for user_id in range(numberOfUsers):
            if not online_status[user_id] and timestamp >= user_offline_time[user_id]:
                online_status[user_id] = True

        if event_type == 'OFFLINE':
            user_id = int(args[0])
            online_status[user_id] = False
            user_offline_time[user_id] = timestamp + 60
            continue  # Skip processing any message events in the same iteration
        elif event_type == 'MESSAGE':
            mentions_string = args[0]
            if mentions_string == 'ALL':
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == 'HERE':
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1
            else:
                mentioned_ids = mentions_string.split()
                for user in mentioned_ids:
                    user_id = int(user[2:])  # Extract the user id after 'id'
                    mentions[user_id] += 1

    return mentions

